function typableWords(text: string, brokenLetters: string): number {
  const broken = new Array(26).fill(false);
  for (const c of brokenLetters) broken[c.charCodeAt(0) - 97] = true;
  let count = 0, bad = false;
  for (let i = 0; i <= text.length; i++) {
    if (i === text.length || text[i] === " ") {
      if (!bad) count++;
      bad = false;
    } else if (broken[text.charCodeAt(i) - 97]) bad = true;
  }
  return count;
}

